// Generated by scripts/build-glossary-data.mjs from content-source/glossary. Do not edit by hand.
export const GLOSSARY_SHARD = Object.freeze({"coin-vs-token":{"slug":"coin-vs-token","cat":"basics","en":"Coin vs token","contentLocale":"tr","term":"Coin ve token farkı","aka":["coin token farkı","token nedir"],"short":"Coin, kendi blockchain'inin yerel varlığıdır (BTC, ETH, SOL gibi); token ise başka bir blockchain üzerinde akıllı kontratla oluşturulan varlıktır (Ethereum üzerindeki USDT veya UNI gibi).","body":[["Coin, ağın çalışması için gereklidir: işlem ücretleri onunla ödenir ve çoğu zaman ağın güvenliği de onunla sağlanır. ",["Bitcoin","bitcoin"]," ağında BTC, ",["Ethereum","ethereum"],"'da ETH, Solana'da SOL bu rolü üstlenir."],["Token ise mevcut bir ağın üzerine bir kontratla eklenir. Ethereum'daki ERC-20 standardı veya BNB Chain'deki BEP-20 standardı buna örnektir. Bir token'ı göndermek için yine o ağın coiniyle gas ödersiniz. Aynı token birden fazla ağda çıkarılmış olabilir; ",["USDT","usdt"]," örneğin hem Ethereum'da hem Tron'da hem de başka ağlarda bulunur."],"Bu ayrım en çok transfer yaparken önem taşır. Borsada çekim yaparken hangi ağı seçtiğiniz, alıcının o ağı destekleyip desteklemediği ve gas için yanınızda yeterli coin olup olmadığı doğrudan sonucu belirler. Günlük konuşmada ise iki kelime sık sık birbirinin yerine kullanılır."],"example":"Cüzdanınızda Ethereum ağında 200 USDT olduğunu ama hiç ETH olmadığını varsayalım. 200 USDT'yi göndermek istediğinizde işlem başarısız olur, çünkü gas ücretini ETH ile ödemeniz gerekir. Cüzdana 0,003 ETH (ETH 3.000 USDT iken yaklaşık 9 USDT) eklediğinizde transfer gerçekleşir. Aynı 200 USDT Tron ağındaysa ücret TRX ile ödenir. Yani token'ın kendisi değil, üzerinde bulunduğu ağın coini ücretleri karşılar.","mistakes":["Token göndermek için gas ödemeye yetecek kadar yerel coin bulundurmamak.","ERC-20 USDT'yi yalnızca TRC-20 kabul eden bir adrese göndermek.","Aynı isimli her token'ın orijinal proje tarafından çıkarıldığını varsaymak; sahte kopyalar yaygındır."],"faq":[{"q":"USDT coin mi token mı?","a":"USDT bir token'dır. Tether tarafından Ethereum, Tron ve diğer birçok blockchain üzerinde akıllı kontratlarla çıkarılır."},{"q":"Token kendi blockchain'ine geçebilir mi?","a":"Evet, bazı projeler önce başka bir ağda token olarak başlar, daha sonra kendi ağlarını kurup token'larını yerel coine dönüştürür. Bu geçişte proje duyurularını dikkatle takip etmek gerekir."}],"title":"Coin ve token farkı nedir?","description":"Coin ile token arasındaki farkı, token transferinde neden ağın coiniyle gas ödendiğini ve doğru ağ seçimini öğrenin.","related":[["layer-1","Katman 1 (Layer 1, L1)","Katman 1 (Layer 1, L1), işlemleri kendi başına doğrulayıp kesinleştiren, kendi uzlaşma mekanizmasına ve yerel coinine sahip temel blockchain ağıdır; Bitcoin, Ethereum ve Solana buna örnektir."],["smart-contract","Akıllı kontrat (smart contract)","Akıllı kontrat (smart contract), bir blockchain üzerinde çalışan ve önceden yazılmış koşullar gerçekleştiğinde kimsenin onayına gerek kalmadan otomatik olarak işlem yapan bir programdır."],["governance-token","Yönetişim token'ı (governance token)","Yönetişim token'ı, sahiplerine bir protokolün veya DAO'nun kararlarında oy kullanma hakkı veren kripto token'ıdır; örneğin UNI, Uniswap yönetişiminde kullanılır."],["tokenomics","Tokenomik (tokenomics)","Tokenomik (tokenomics), bir token'ın toplam arzını, dağıtımını, kilit açılma takvimini, kullanım alanlarını ve arzı artıran ya da azaltan mekanizmaları kapsayan ekonomik tasarımıdır."],["altcoin","Altcoin","Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar."]],"lesson":null,"coin":{"slug":"ethereum","name":"Ethereum","symbol":"ETH"},"tool":null,"cta":false},"memecoin":{"slug":"memecoin","cat":"basics","en":"Memecoin","contentLocale":"tr","term":"Memecoin","aka":["meme coin","meme token","mim coin"],"short":"Memecoin, bir internet şakası, hayvan figürü veya popüler kültür öğesinden ilham alan, değeri büyük ölçüde topluluk ilgisine ve spekülasyona dayanan bir kripto paradır; Dogecoin ve Shiba Inu en bilinen örneklerdir.","body":["Memecoin'lerin çoğu belirgin bir ürün veya gelir modeli sunmaz. Fiyatı sosyal medya gündemi, ünlülerin paylaşımları ve topluluğun heyecanı hareket ettirir. Bu nedenle çok kısa sürede büyük yükselişler de, sert çöküşler de görülebilir.",["Solana ve Base gibi düşük ücretli ağlarda bir token oluşturmak dakikalar sürer. Her gün binlerce yeni memecoin çıkar ve bunların büyük çoğunluğu kısa sürede değerini kaybeder. ",["Rug pull","rug-pull"],", yani geliştiricinin likiditeyi çekip kaçması, bu alanda sık rastlanan bir dolandırıcılık türüdür."],["Bir memecoin'e bakarken ",["likidite","liquidity"]," havuzunun kilitli olup olmadığını, arzın ne kadarının birkaç cüzdanda toplandığını ve kontratın satışı engelleyen bir kod içerip içermediğini kontrol etmek işe yarar. Büyük borsalarda listelenmiş olması likiditeyi artırır ama riski ortadan kaldırmaz."]],"example":["Bir memecoin'e 200 ",["USDT","usdt"]," ile girdiğinizi düşünün. İlk gün fiyat 3 katına çıkar ve pozisyonunuz 600 USDT olur. Ertesi hafta erken alıcılar satışa geçer ve fiyat zirveden yüzde 80 düşer: 600 x 0,20 = 120 USDT. Başlangıca göre 80 USDT zarardasınız. Likiditesi düşük bir havuzda 600 USDT'lik satış emri tek başına fiyatı yüzde 5 daha aşağı itebilir; bu yüzden ",["kâğıt üzerindeki kâr","unrealized-pnl"]," ile gerçekten satabileceğiniz tutar farklıdır."],"mistakes":["Sosyal medyada hızla yayılan bir memecoin'e kontratı kontrol etmeden büyük tutarla girmek.","Kontrat adresini resmi kaynaktan değil, rastgele bir paylaşımdan kopyalayıp sahte token almak.","Kaybetmeyi göze alabileceğinizden büyük bir pozisyon açıp yüksek oynaklıkta panik satış yapmak."],"faq":[{"q":"Memecoin'ler değersiz mi?","a":"Değerleri tamamen piyasanın onlara biçtiği fiyattır ve büyük ölçüde ilgiye bağlıdır. Dogecoin gibi bazıları uzun yıllar varlığını sürdürdü, ancak çoğu yeni memecoin kısa sürede ilgiyi kaybeder."},{"q":"Memecoin rug pull nasıl anlaşılır?","a":"Likiditenin kilitli olmaması, arzın büyük kısmının tek cüzdanda olması ve satışı engelleyen kontrat özellikleri başlıca uyarı işaretleridir. Token tarayıcı araçları bu bilgilerin bir kısmını gösterir."}],"title":"Memecoin nedir? Meme coin riskleri","description":"Memecoin'in ne olduğunu, fiyatının neden bu kadar sert hareket ettiğini ve rug pull gibi riskleri nasıl fark edeceğinizi öğrenin.","related":[["altcoin","Altcoin","Altcoin, Bitcoin dışındaki tüm kripto paralar için kullanılan genel bir terimdir; Ethereum ve Solana gibi büyük ağlardan küçük proje token'larına ve memecoin'lere kadar geniş bir yelpazeyi kapsar."],["rug-pull","Rug pull (halı çekme)","Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."],["liquidity","Likidite (Liquidity)","Likidite, bir varlığın fiyatı fazla etkilenmeden ne kadar hızlı ve kolay alınıp satılabildiğini gösteren ölçüdür."],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."]],"lesson":null,"coin":{"slug":"dogecoin","name":"Dogecoin","symbol":"DOGE"},"tool":"/topics/meme-coins","cta":true},"hodl":{"slug":"hodl","cat":"basics","en":"HODL","contentLocale":"tr","term":"HODL","aka":["hodl","hodlamak","hodler"],"short":"HODL, kısa vadeli fiyat dalgalanmalarına rağmen kripto paraları satmadan uzun süre elde tutma stratejisini ifade eden, 2013'teki bir forum yazısındaki yazım hatasından doğmuş bir terimdir.","body":[["Terim, bir kullanıcının ",["Bitcoin","bitcoin"]," forumunda hold kelimesini yanlış yazmasıyla ortaya çıktı ve kısa sürede topluluk diline yerleşti. Daha sonra Hold On for Dear Life (canını dişine takarak tut) açılımı da yaygınlaştı."],["HODL yaklaşımında amaç piyasayı zamanlamaya çalışmak yerine uzun vadeli bir görüşe dayanarak varlığı tutmaktır. Bu, sık işlem ücretlerinden ve duygusal alım satımlardan kaçınmayı sağlar. Genellikle düzenli alım (",["DCA","dollar-cost-averaging"],") ve soğuk cüzdanda saklama ile birlikte uygulanır."],"HODL her coin için uygun değildir. Bitcoin gibi uzun geçmişi olan bir varlıkta mantıklı görünen strateji, kısa sürede ilgisini kaybeden bir projede kalıcı kayba yol açabilir. Uzun vadeli tutmak, varlığı düzenli olarak yeniden değerlendirmemek anlamına gelmemelidir."],"example":["Her ay 150 ",["USDT","usdt"],"'lik BTC aldığınızı ve 24 ay boyunca hiç satmadığınızı varsayalım. Toplam 3.600 USDT yatırmış olursunuz. Bu süre içinde fiyat bir dönem yüzde 40 düşüp sonra toparlanabilir; portföy değeri bir noktada 2.500 USDT'ye inip daha sonra 4.000 USDT'ye çıkabilir. HODL eden biri ara dönemde satış yapmadığı için yalnızca alım ücretlerini öder; her dalgada alıp satan biri ise her işlemde yüzde 0,1 ücret ve yanlış zamanlama riskiyle karşılaşır."],"mistakes":["Projenin temellerini hiç takip etmeden her koşulda tutmayı sürdürmek.","Uzun vadeli tutulan coinleri yıllarca bir borsada bırakıp saklama riskini göz ardı etmek.","Kısa vadede ihtiyaç duyacağınız parayla HODL stratejisi uygulamak."],"faq":[{"q":"HODL ne demek?","a":"Kripto paraları fiyat dalgalanmalarına rağmen satmadan uzun süre tutmak demektir. Yanlış yazılmış hold kelimesinden doğmuş bir topluluk terimidir."},{"q":"HODL iyi bir strateji mi?","a":"Uzun vadeli görüşünüze güvendiğiniz ve kısa vadede ihtiyaç duymayacağınız bir tutarla uygulandığında işlem ücretlerini ve duygusal kararları azaltır. Ancak tuttuğunuz varlığın değer kaybetme riskini ortadan kaldırmaz."}],"title":"HODL nedir? Kriptoda hodlamak ne demek?","description":"HODL teriminin nereden geldiğini, uzun vadeli tutma stratejisinin artılarını ve hangi durumlarda riskli olduğunu öğrenin.","related":[["dollar-cost-averaging","Düzenli alım stratejisi (DCA)","DCA (dollar-cost averaging), fiyatı tahmin etmeye çalışmadan belirli aralıklarla sabit tutarda kripto alarak ortalama maliyeti zamana yayma stratejisidir."],["cold-wallet","Soğuk cüzdan (cold wallet)","Soğuk cüzdan, özel anahtarları internete hiç bağlanmayan bir cihazda veya ortamda saklayarak uzaktan çalınma riskini büyük ölçüde azaltan kripto saklama yöntemidir."],["bear-market","Ayı piyasası (bear market)","Ayı piyasası (bear market), fiyatların uzun bir dönem boyunca genel olarak düştüğü, yatırımcı karamsarlığının ve düşük ilginin hakim olduğu piyasa evresidir."],["volatility","Volatilite (oynaklık)","Volatilite (oynaklık), bir varlığın fiyatının belirli bir süre içinde ne kadar ve ne hızla dalgalandığının ölçüsüdür; yüksek volatilite büyük ve ani fiyat hareketleri demektir."]],"lesson":null,"coin":{"slug":"bitcoin","name":"Bitcoin","symbol":"BTC"},"tool":null,"cta":false},"liquidity-pool":{"slug":"liquidity-pool","cat":"defi","en":"Liquidity pool","contentLocale":"tr","term":"Likidite havuzu (liquidity pool)","aka":["liquidity pool","LP havuzu","havuz"],"short":"Likidite havuzu, kullanıcıların yatırdığı iki veya daha fazla token'ın bir akıllı sözleşmede kilitlendiği ve DEX'lerde takasların doğrudan bu havuzdan yapıldığı fon havuzudur.","body":[["Bir havuza ",["likidite","liquidity"]," eklemek için genellikle iki token'ı eşit değerde yatırırsınız, örneğin 1.000 ",["USDC","usdc"]," değerinde ",["ETH","ethereum"]," ve 1.000 USDC. Karşılığında havuzdaki payınızı temsil eden bir LP token'ı veya Uniswap v3 gibi modellerde bir pozisyon ",["NFT","nft"],"'si alırsınız."],"Havuzda yapılan her takastan bir ücret kesilir ve bu ücret likidite sağlayıcılara payları oranında dağıtılır. Bu, likidite sağlamanın temel gelir kaynağıdır. Bazı protokoller ayrıca kendi token'ları ile ek ödül de verir.",["Riskler arasında ",["geçici kayıp (impermanent loss)","impermanent-loss"],", ",["akıllı sözleşme","smart-contract"]," açıkları ve düşük kaliteli token'larda rug pull vardır. Yeni çıkmış bir token ile açılan havuzda, geliştirici likiditeyi çekerse diğer token'ın değeri kaybolabilir. Havuzun derinliği, işlem hacmi ve token'ların kalitesi riski doğrudan etkiler."]],"example":"Toplam değeri 500.000 USDC olan bir ETH/USDC havuzuna 5.000 USDC değerinde likidite eklediğinizi varsayalım; payınız yüzde 1. Havuzun günlük işlem hacmi 200.000 USDC ve ücret yüzde 0,3 ise havuz günde 600 USDC ücret toplar. Sizin payınız yaklaşık 6 USDC olur. Ancak bu sırada ETH fiyatı güçlü biçimde hareket ederse geçici kayıp bu ücret gelirini aşabilir.","mistakes":["Sadece ekranda görünen yıllık getiriye bakıp geçici kaybı hesaba katmamak.","LP token'ını kaybetmek veya bilinmeyen bir siteye onaylamak.","Yeni ve kilitli likiditesi olmayan token havuzlarına büyük tutar yatırmak."],"faq":[{"q":"Likidite havuzuna para yatırmak kârlı mı?","a":"Takas ücretleri gelir sağlar, ancak geçici kayıp ve sözleşme riskleri bu geliri azaltabilir veya aşabilir. Sonuç, havuzun hacmine ve fiyat hareketine bağlıdır."},{"q":"LP token'ı ne işe yarar?","a":"Havuzdaki payınızı temsil eder. Likiditeyi geri çekerken bu token'ı iade edersiniz; bazı protokollerde ek ödül için stake edilebilir."}],"title":"Likidite havuzu nedir? Liquidity pool nasıl çalışır?","description":"Likidite havuzunun nasıl çalıştığını, likidite sağlayıcıların nasıl ücret kazandığını ve hangi riskleri taşıdığını öğrenin.","related":[["amm","Otomatik piyasa yapıcı (AMM)","Otomatik piyasa yapıcı (AMM), alıcı ve satıcıları bir emir defterinde eşleştirmek yerine, likidite havuzundaki token oranlarına göre fiyatı bir formülle belirleyen ve takası doğrudan havuzla yaptıran DEX modelidir."],["impermanent-loss","Geçici kayıp (impermanent loss)","Geçici kayıp, bir likidite havuzuna yatırdığınız token'ların fiyat oranı değiştiğinde, pozisyonunuzun değerinin aynı token'ları cüzdanda tutmaya göre daha düşük kalması durumudur."],["yield-farming","Getiri çiftçiliği (yield farming)","Getiri çiftçiliği (yield farming), kripto varlıkları DeFi protokollerine likidite, borç veya stake olarak yatırıp ücret, faiz ve ödül token'larıyla getiri elde etmeye çalışma stratejisidir."],["rug-pull","Rug pull (halı çekme)","Rug pull, bir kripto projesinin geliştiricilerinin yatırımcı parasını toplayıp likiditeyi çekerek, token'ları satarak veya akıllı sözleşmedeki gizli yetkileri kullanarak projeyi aniden terk ettiği dolandırıcılıktır."]],"lesson":null,"coin":{"slug":"uniswap","name":"Uniswap","symbol":"UNI"},"tool":null,"cta":false},"perp-dex":{"slug":"perp-dex","cat":"defi","en":"Perp DEX (on-chain perpetuals)","contentLocale":"tr","term":"Perp DEX (zincir üstü sürekli vadeli işlemler)","aka":["perp DEX","merkeziyetsiz vadeli işlem borsası","on-chain perpetual"],"short":"Perp DEX, sürekli (perpetual) vadeli kontratların kendi cüzdanınızdan, merkezi bir borsaya fon emanet etmeden, akıllı sözleşmeler veya kendi blokzinciri üzerinde işlem gördüğü merkeziyetsiz borsadır.","body":[["Perp ",["DEX","dex"],"'lerde, merkezi borsalardaki gibi kaldıraçlı ",["long ve short pozisyon","long-and-short"]," açabilirsiniz. Teminatınızı genellikle ",["USDC","usdc"]," olarak protokole yatırırsınız. Hyperliquid kendi blokzincirinde çalışan bir zincir üstü ",["emir defteri","order-book"]," kullanır; dYdX de emir defteri modelini kullanır; GMX gibi protokoller ise bir ",["likidite","liquidity"]," havuzuna karşı işlem yapmanızı sağlar."],["Merkezi borsalardaki gibi ",["fonlama oranı","funding-rate"],", işaret fiyatı ve tasfiye (likidasyon) kavramları burada da geçerlidir. Fonlama oranının uygulanma sıklığı platformdan platforma değişir; bazı perp DEX'ler fonlamayı saatlik uygular. Kontrat detaylarını her platformun dokümantasyonunda kontrol etmek gerekir."],"Avantajları şeffaflık ve saklama dışı kontroldür: pozisyonlar ve tasfiyeler zincirde görülebilir. Riskleri ise akıllı sözleşme ve köprü açıkları, oracle sorunları, düşük likiditeli piyasalarda kayma ve borsa kapanırsa başvurulacak bir müşteri hizmeti olmamasıdır. Yasal erişim de ülkeye göre farklılık gösterebilir."],"example":"Bir perp DEX'e 1.000 USDC teminat yatırıp 5x kaldıraçla 5.000 USDC'lik ETH long açtığınızı varsayalım; ETH 2.500 USDC, pozisyon 2 ETH. ETH yüzde 4 yükselip 2.600 USDC olursa kârınız 2 × 100 = 200 USDC olur, teminata göre yüzde 20. Fonlama oranı saatlik yüzde 0,001 ise, 24 saatte 5.000 × 0,00024 = 1,2 USDC fonlama ödersiniz. ETH yaklaşık yüzde 18 düşerse, bakım marjına göre tasfiye riskiyle karşılaşırsınız.","mistakes":["Perp DEX'in fonlama aralığının merkezi borsayla aynı olduğunu varsaymak.","Teminatı köprülerken ağ ve köprü riskini hesaba katmamak.","Düşük likiditeli piyasalarda büyük piyasa emri vermek."],"faq":[{"q":"Perp DEX'te KYC gerekir mi?","a":"Çoğu perp DEX cüzdanla bağlanmaya izin verir ve kimlik doğrulaması istemez. Ancak bazı platformlar belirli ülkelere erişimi kısıtlar."},{"q":"Perp DEX merkezi borsadan daha mı güvenli?","a":"Borsa iflası ve fon dondurma riskini azaltır, ama sözleşme, oracle ve likidite riskleri ekler. Hangisinin uygun olduğu kullanım şeklinize bağlıdır."}],"title":"Perp DEX nedir? Zincir üstü vadeli işlemler nasıl çalışır?","description":"Perp DEX'lerin nasıl çalıştığını, merkezi vadeli işlem borsalarından farkını, fonlama ve tasfiye risklerini öğrenin.","related":[["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["dex","Merkeziyetsiz borsa (DEX)","Merkeziyetsiz borsa (DEX), kullanıcıların kendi cüzdanlarından, bir şirkete fon emanet etmeden, akıllı sözleşmeler aracılığıyla kripto takası yaptığı borsadır."],["funding-rate","Fonlama oranı (Funding rate)","Fonlama oranı, sürekli (perpetual) vadeli kontrat fiyatını spot fiyata yakın tutmak için long ve short pozisyon sahipleri arasında düzenli aralıklarla yapılan ödemenin oranıdır."],["non-custodial-wallet","Saklama dışı cüzdan (non-custodial wallet)","Saklama dışı cüzdan, özel anahtarları yalnızca sizin kontrol ettiğiniz, bu yüzden fonlarınızı sizden başka kimsenin taşıyamadığı, donduramadığı veya sizin yerinize kurtaramadığı bir kripto cüzdanıdır."]],"lesson":null,"coin":{"slug":"hyperliquid","name":"Hyperliquid","symbol":"HYPE"},"tool":"/funding-rates","cta":false},"copy-trading":{"slug":"copy-trading","cat":"exchange-features","en":"Copy trading","contentLocale":"tr","term":"Kopya işlem (copy trading)","aka":["copy trading","kopya ticaret","işlem kopyalama","copy trade"],"short":"Kopya işlem (copy trading), seçtiğiniz bir trader'ın açtığı ve kapattığı pozisyonların, belirlediğiniz tutar ve oranla sizin hesabınızda otomatik olarak tekrarlanmasıdır.","body":["OKX, Bybit ve Bitget gibi borsalar kopya işlem sunar. Platformda 'lider trader' veya 'usta trader' denen kişilerin geçmiş performansı, maksimum düşüşü (drawdown) ve takipçi sayısı listelenir. Siz bir lider seçer, ayırdığınız sermayeyi ve pozisyon başına tutarı belirlersiniz.","Kopya işlem çoğunlukla vadeli işlemlerde ve kaldıraçla kullanılır. Bu, liderin bir hatasının sizin hesabınızda da aynı şekilde, hatta giriş fiyatı farkı nedeniyle daha kötü sonuçlanabileceği anlamına gelir. Ayrıca kârınızdan liderin aldığı bir kâr payı (profit share) kesilir.","Liderin yüksek getiri gösteren kısa geçmişi, çoğu zaman yüksek riskle elde edilmiştir. Maksimum düşüşe, işlem sayısına ve ne kadar süredir işlem yaptığına bakmak ve kendi zarar durdur sınırınızı koymak daha sağlıklıdır."],"example":["Kopya işlem için 1.000 ",["USDT","usdt"]," ayırdığınızı ve liderin hesabının 10.000 USDT olduğunu varsayalım. Orantılı kopyalamada lider hesabının yüzde 20'siyle, yani 2.000 USDT ile long açarsa siz 200 USDT ile aynı pozisyonu açarsınız. Pozisyon yüzde 15 kârla kapanırsa siz 30 USDT kazanırsınız. Lider yüzde 10 kâr payı alıyorsa bunun 3 USDT'si ona gider, size 27 USDT kalır. Aynı pozisyon yüzde 15 zararla kapanırsa 30 USDT kaybedersiniz ve kâr payı ödemezsiniz."],"mistakes":["Sadece son 7 günün getirisine bakarak lider seçmek.","Tüm sermayeyi tek bir lidere ayırıp kopya hesabı için zarar sınırı koymamak.","Liderin kullandığı kaldıracı ve pozisyon büyüklüğünü kontrol etmemek."],"faq":[{"q":"Copy trading kârlı mı?","a":"Sonuç tamamen seçtiğiniz liderin performansına ve risk yönetimine bağlıdır. Geçmiş getiri geleceği göstermez ve kayıplar da aynı şekilde kopyalanır."},{"q":"Kopya işlemde lider ne kazanır?","a":"Lider genellikle takipçilerin kârından belirli bir yüzde alır. Oran ve hesaplama yöntemi borsaya ve lidere göre değişir."}],"title":"Copy trading nedir? Kopya işlem nasıl çalışır","description":"Kopya işlem (copy trading) nedir, lider trader nasıl seçilir, kâr payı nasıl hesaplanır ve riskler nelerdir, örnekle öğrenin.","related":[["perpetual-futures","Sürekli vadeli kontrat (Perpetual futures)","Sürekli vadeli kontrat (perpetual), vade tarihi olmayan ve fiyatı fonlama oranı mekanizmasıyla spot fiyata yakın tutulan bir kripto vadeli işlem sözleşmesidir."],["leverage","Kaldıraç (Leverage)","Kaldıraç, yatırdığınız teminatın birkaç katı büyüklüğünde pozisyon açmanızı sağlayan ve hem kazancı hem kaybı aynı oranda büyüten bir işlem aracıdır."],["risk-reward-ratio","Risk-ödül oranı (Risk-reward ratio)","Risk-ödül oranı, bir işlemde zarar durdur seviyesine kadar göze aldığınız olası kaybı, kâr al hedefindeki olası kazançla karşılaştıran orandır."],["grid-trading-bot","Grid trading botu (ızgara botu)","Grid trading botu, belirlediğiniz fiyat aralığını eşit basamaklara bölüp her basamakta otomatik alım ve satım emirleri vererek yatay piyasadaki dalgalanmalardan küçük kârlar toplayan bottur."]],"lesson":null,"coin":null,"tool":"/compare","cta":true}});
